{

    internal InnerAutoMLJobImageClassificationJobConfigFactory ImageClassificationJobConfigFactory { get; set; }

    internal InnerAutoMLJobTimeSeriesForecastingJobConfigFactory TimeSeriesForecastingJobConfigFactory { get; set; }

    internal InnerAutoMLJobTextGenerationJobConfigFactory TextGenerationJobConfigFactory { get; set; }

    internal InnerAutoMLJobTextClassificationJobConfigFactory TextClassificationJobConfigFactory { get; set; }

    internal InnerAutoMLJobTabularJobConfigFactory TabularJobConfigFactory { get; set; }

    protected override Humidifier.SageMaker.AutoMLJobTypes.AutoMLProblemTypeConfig Create()
    {
        var autoMLProblemTypeConfigResult = CreateAutoMLProblemTypeConfig();
        factoryAction?.Invoke(autoMLProblemTypeConfigResult);

        return autoMLProblemTypeConfigResult;
    }

    private Humidifier.SageMaker.AutoMLJobTypes.AutoMLProblemTypeConfig CreateAutoMLProblemTypeConfig()
    {
        var autoMLProblemTypeConfigResult = new Humidifier.SageMaker.AutoMLJobTypes.AutoMLProblemTypeConfig();

        return autoMLProblemTypeConfigResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.AutoMLJobTypes.AutoMLProblemTypeConfig result)
    {
        base.CreateChildren(result);

        result.ImageClassificationJobConfig ??= ImageClassificationJobConfigFactory?.Build();
        result.TimeSeriesForecastingJobConfig ??= TimeSeriesForecastingJobConfigFactory?.Build();
        result.TextGenerationJobConfig ??= TextGenerationJobConfigFactory?.Build();
        result.TextClassificationJobConfig ??= TextClassificationJobConfigFactory?.Build();
        result.TabularJobConfig ??= TabularJobConfigFactory?.Build();
    }

} // End Of Class

